#!/usr/bin/env bash
# Prints the Homebrew formula for a release.
# Usage: homebrew-formula.sh VERSION MACOS_SHA256 LINUX_SHA256
set -euo pipefail

version="$1"
macos_sha="$2"
linux_sha="$3"
base="https://github.com/vangheem/dullview/releases/download/v${version}"

cat <<FORMULA
# Generated by vangheem/dullview's release workflow; edits here are overwritten.
class Dullview < Formula
  desc "Markdown slide decks with templates, PowerPoint import and live reload"
  homepage "https://github.com/vangheem/dullview"
  version "${version}"
  license "MIT"

  on_macos do
    url "${base}/dullview-macos-universal.tar.gz"
    sha256 "${macos_sha}"
  end

  on_linux do
    on_intel do
      url "${base}/dullview-linux-x86_64.tar.gz"
      sha256 "${linux_sha}"
    end
  end

  def install
    bin.install "dullview"
  end

  test do
    system bin/"dullview", "--init", testpath/"deck"
    assert_path_exists testpath/"deck/_templates/default.md"
  end
end
FORMULA
